    in the text.
    Taken from http://djangosnippets.org/snippets/57/
    """
    def _escape(candidate):
        """
        Escape a single candidate
        """
        # If it's a SafeString, don't do anythig else
        if isinstance(candidate, mark_safe.__class__):
            return candidate
        # If it's a string, escape links, < and > signs
        elif isinstance(candidate, basestring):
            return conditional_escape(candidate).replace('<','&lt;').replace('>', '&gt;')
