def link(parser, token):
    """
    Converts its argument to a variable
    """
    parsed = token.contents.split(' ', 1)
    url_token = parser.parse_single_filter(parsed[0])
    text = parser.parse( ('/", ', '/'))
    parser.next_token()
    text = text.nodelist[0]
    return LinkNode(url_token, text)


class VariableNode(template.Node):
    def __init__(self, variable):
        self.variable = variable

    def render(self, context):
        return str(self.variable.resolve(context))


class LinkNode(template.Node):
    def __init__(self, url, text):
        self.url = url
        self.text = text

    def render(self, context):
        try:
            url = self.url.resolve(context)
            text = self.text.resolve(context)
        except VariableDoesNotExist:
            return
        return '<a href="{}">{}</a>'.format(url, text)


